CREATE OR REPLACE FUNCTION public.verification_validate() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN CASE TG_TABLE_NAME WHEN 'company_verifications' THEN IF NEW.status NOT IN ('not_ordered','waiting_payment','checking','certified','needs_fix') THEN RAISE EXCEPTION 'Invalid verification status'; END IF; WHEN 'company_verification_checks' THEN IF NEW.key NOT BETWEEN 1 AND 6 OR NEW.result NOT IN ('match','mismatch') THEN RAISE EXCEPTION 'Invalid verification check'; END IF; NEW.recorded_at:=now(); WHEN 'verification_orders' THEN IF NEW.method NOT IN ('promptpay','card','transfer') OR NEW.status NOT IN ('pending','paid','refunded') OR NEW.amount<0 OR NEW.vat<0 OR NEW.total<>NEW.amount+NEW.vat OR (NEW.method='transfer' AND NEW.slip IS NULL) THEN RAISE EXCEPTION 'Invalid verification order'; END IF; WHEN 'verification_access' THEN IF NEW.via NOT IN ('plan','paid','contract') THEN RAISE EXCEPTION 'Invalid verification access'; END IF; END CASE; RETURN NEW; END; $$;
CREATE OR REPLACE FUNCTION public.verification_checks_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE vid uuid; cid uuid; n integer; bad integer; ts timestamptz:=now(); BEGIN IF TG_OP='DELETE' THEN vid:=OLD.verification_id; ELSE vid:=NEW.verification_id; END IF; SELECT company_id INTO cid FROM public.company_verifications WHERE id=vid; SELECT count(*),count(*) FILTER(WHERE c.result='mismatch') INTO n,bad FROM public.company_verification_checks c JOIN public.company_verifications v ON v.id=c.verification_id WHERE c.verification_id=vid AND (v.started_at IS NULL OR c.recorded_at>=v.started_at); IF n=6 THEN UPDATE public.company_verifications SET status=CASE WHEN bad=0 THEN 'certified' ELSE 'needs_fix' END,checked_at=ts WHERE id=vid; UPDATE public.startups SET registration_verified_at=CASE WHEN bad=0 THEN ts ELSE NULL END WHERE id=cid; IF EXISTS(SELECT 1 FROM public.company_verification_checks WHERE verification_id=vid AND key=1 AND result='mismatch') THEN UPDATE public.verification_usage SET returned_at=ts WHERE company_id=cid AND returned_at IS NULL; UPDATE public.verification_orders SET refund_requested_at=ts WHERE company_id=cid AND status='paid'; END IF; ELSE UPDATE public.company_verifications SET status='checking',checked_at=NULL WHERE id=vid; UPDATE public.startups SET registration_verified_at=NULL WHERE id=cid; END IF; IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF; END; $$;
CREATE OR REPLACE FUNCTION public.verification_badge_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.registration_verified_at IS NOT NULL AND (TG_OP='INSERT' OR NEW.registration_verified_at IS DISTINCT FROM OLD.registration_verified_at) THEN IF NOT EXISTS(SELECT 1 FROM public.company_verifications v WHERE v.company_id=NEW.id AND v.status='certified' AND (SELECT count(*) FROM public.company_verification_checks c WHERE c.verification_id=v.id AND c.result='match' AND (v.started_at IS NULL OR c.recorded_at>=v.started_at))=6) THEN RAISE EXCEPTION 'Certification requires all six current checks to match'; END IF; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.verification_badge_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER verification_badge_guard BEFORE INSERT OR UPDATE OF registration_verified_at ON public.startups FOR EACH ROW EXECUTE FUNCTION public.verification_badge_guard();
CREATE OR REPLACE FUNCTION public.verification_pipeline_valid(_uid uuid,_company uuid,_pipeline uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.deal_pipelines d WHERE d.id=_pipeline AND d.buyer_user_id=_uid AND d.startup_id=_company AND d.nda_approved_at IS NOT NULL AND d.status NOT IN ('declined','withdrawn','revoked','ended') AND coalesce(d.nda_expires_at,d.nda_approved_at+interval '730 days')>now()); $$;
REVOKE ALL ON FUNCTION public.verification_pipeline_valid(uuid,uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.verification_pipeline_valid(uuid,uuid,uuid) TO authenticated,service_role;